ius:10px;color:var(--muted);font-size:13px}.empty{padding:20px;background:#fff;border:1px solid var(--line);border-radius:14px}.login-wrap{max-width:520px;margin:70px auto;padding:0 20px}.kaart{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px}.veld{margin:14px 0}.veld label{display:block;font-weight:700;margin-bottom:6px}.veld input{width:100%;border:1px solid #cfcab7;border-radius:9px;padding:11px;font:inherit}.kaart button{border:0;background:var(--primary);color:#fff;border-radius:9px;padding:11px 16px;font:inherit;font-weight:750}.melding.fout{background:#fdeceb;color:var(--danger);padding:11px;border-radius:8px}.sub,.hint{color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.grid{grid-template-columns:1fr;gap:14px}.groep{padding:17px}.wrap{margin-top:22px;padding:0 16px 48px}.top{position:static;padding:13px 16px}.topin{align-items:flex-start;flex-direction:column;gap:8px}.user{width:100%;justify-content:space-between}.module{padding:12px}.subnav{padding:0 12px 11px 27px}}
</style><link rel="stylesheet" href="ui-2026.css"></head><body class="beheer-dashboard"><?php if(!$ingelogd):?><div class="login-wrap"><?php authInlogFormulier(siteNaam().' beheer');?></div><?php else:?><header class="top"><div class="topin"><div><span class="brand"><?=beheerShellEsc(siteNaam())?> beheer</span> · <a href="../index.html">website</a> · <a href="../leden/">mijn vereniging</a></div><div class="user"><span>Ingelogd als <strong><?=beheerShellEsc($huidigeGebruiker)?></strong></span><form method="post"><input type="hidden" name="formulier" value="uitloggen"><input type="hidden" name="csrf" value="<?=beheerShellEsc($csrfToken)?>"><button class="logout" type="submit">Uitloggen</button></form></div></div></header><main class="wrap"><div class="hero"><h1>Beheer</h1><p>Website, vereniging en systeembeheer vanuit één modulaire omgeving.</p></div><?php if(!$groepen):?><div class="empty">Voor dit account zijn geen beheeronderdelen beschikbaar.</div><?php else:?><div class="grid"><?php foreach($groepen as $categorie=>$items):?><section class="groep"><h2><?=beheerShellEsc($categorie)?></h2><div class="links"><?php foreach($items as $def):$subs=beheerShellSubmenu((string)($def['_sleutel']??''),$componenten);?><div class="moduleblok"><a class="module" href="<?=beheerShellEsc($def['route']??'')?>"><span><?=beheerShellEsc($def['label']??'')?></span><span class="meta">open →</span></a><?php if($subs):?><div class="subnav"><?php foreach($subs as $sub):?><a href="<?=beheerShellEsc($sub['route'])?>"><?=beheerShellEsc($sub['label'])?></a><?php endforeach;?></div><?php endif;?></div><?php endforeach;?></div></section><?php endforeach;?></div><?php endif;?><?php if($build):?><div class="build">DEV build: <strong><?=beheerShellEsc($build['commit_short']??'')?></strong> · branch <?=beheerShellEsc($build['branch']??'')?> · run <?=beheerShellEsc($build['run_number']??'')?> · <?=beheerShellEsc($build['deployed_at_utc']??'')?></div><?php endif;?></main><?php endif;?></body></html>
